function integerReplacement(n) {
  // Try both choices for every odd number, remembering results that were already worked out.
  const memo = new Map();
  const best = (value) => {
    if (value === 1) return 0;
    if (memo.has(value)) return memo.get(value);
    const result = value % 2 === 0 ? 1 + best(value / 2) : 1 + Math.min(best(value - 1), best(value + 1));
    memo.set(value, result);
    return result;
  };
  return best(n);
}

